def transform(grid):
    if not grid:
        return grid

    rows, cols = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]

    # Regular components (for all colors except background)
    visited = [[False]*cols for _ in range(rows)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(r, c, color):
        stack = [(r, c)]
        visited[r][c] = True
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
        return comp

    result = [[background]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background or visited[r][c]:
                continue

            color = grid[r][c]
            comp = dfs(r, c, color)

            crs = [x[0] for x in comp]
            ccs = [x[1] for x in comp]
            h = max(crs) - min(crs) + 1
            w = max(ccs) - min(ccs) + 1

            if h * w == len(comp) and len(comp) >= 2:
                for rr, cc in comp:
                    result[rr][cc] = color

    # Handle 0s separately as components
    visited_0 = [[False]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited_0[r][c]:
                comp = []
                stack = [(r, c)]
                visited_0[r][c] = True

                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    for dr, dc in directions:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited_0[nr][nc] and grid[nr][nc] == 0:
                            visited_0[nr][nc] = True
                            stack.append((nr, nc))

                crs = [x[0] for x in comp]
                ccs = [x[1] for x in comp]
                h = max(crs) - min(crs) + 1
                w = max(ccs) - min(ccs) + 1

                if h * w == len(comp) and len(comp) >= 2:
                    for rr, cc in comp:
                        result[rr][cc] = 0

    return result
